/**
 * Registers the PWA service worker (public/sw.js, generated by next-pwa) on every page.
 *
 * next-pwa's `register: true` injects its registration into the Pages Router entry, which
 * the App Router never loads, so production had no worker unless the user happened to turn
 * on notifications (WhatsApp / reminders register it then). Without a worker nothing is
 * cached and the installed app cannot open offline. Development keeps no worker on purpose
 * (see components/molecules/Layout.jsx).
 */
export function registerServiceWorker() {
	if (
		typeof window === 'undefined' ||
		process.env.NODE_ENV !== 'production' ||
		!('serviceWorker' in navigator) ||
		!window.isSecureContext
	) {
		return;
	}
	const register = () => {
		navigator.serviceWorker.register('/sw.js', { scope: '/' }).catch(error => {
			console.warn('Service worker registration failed', error);
		});
	};
	// After load, so caching the app shell never competes with the first paint.
	if (document.readyState === 'complete') register();
	else window.addEventListener('load', register, { once: true });
}
